def fetch(call, waits=(1, 2, 4)):
    for delay in waits:
        result = call()
        if result.ok:
            return result
        time.sleep(delay)
    raise RuntimeError('failed')

def permit(used, soft_limit, burst, is_admin):
    ceiling = soft_limit + burst
    if used < soft_limit:
        return True, 'normal'
    if is_admin and used < ceiling:
        return True, 'burst'
    return False, 'blocked'
